HOST="import pathlib,subprocess,json,gzip,hashlib,time,urllib.request\nscope=IDENTITY_ENV;exec(compile(IDENTITY,'identity','exec'),scope);model_identity=scope['model_identity']\nroot=pathlib.Path('/data/wio/inference-foundry/glm53/runs/20261018T-L08-sglang-C32-ops-window-L04-rollback-v2');supervisor=json.loads((root/'supervisor-status.json').read_text());provider=json.loads((root/'provider-status.json').read_text());assert provider['phase']=='READY'\narchive=pathlib.Path(ARCHIVE);assert not archive.exists();archive.mkdir(parents=True)\nlogscope={};exec(compile(STREAM,'stream','exec'),logscope)\nout={'project_id':'glm53','framework':'sglang','node':NODE,'container_id':CID,'actual_model_identity':model_identity,'supervisor':supervisor,'provider_phase':provider['phase'],'monotonic_ns':time.monotonic_ns(),'model_requests':0,'SDK_init_calls':0,'logs':{},'persistent_audit':{}}\nfor stream in ['stdout','stderr']:\n with (root/('model.'+stream+'.txt')).open('rb') as file:out['logs'][stream]=logscope['summarize_log_stream'](file,archive/('model.'+stream+'.gz'))\ndef cmd(args,timeout=30):\n p=subprocess.run(args,capture_output=True,text=True,timeout=timeout);return {'rc':p.returncode,'stdout':p.stdout,'stderr':p.stderr}\nout['npu']=cmd(['npu-smi','info']);assert out['npu']['rc']==0;rows=[]\nfor line in out['npu']['stdout'].split('Process id',1)[-1].splitlines():\n cols=[v.strip() for v in line.split('|')]\n if len(cols)>=5 and len(cols[1].split())==2 and all(v.isdigit() for v in cols[1].split()) and cols[2].isdigit():\n  proc=pathlib.Path('/proc')/cols[2];assert CID in (proc/'cgroup').read_text();rows.append({'card':int(cols[1].split()[0]),'chip':int(cols[1].split()[1]),'host_pid':int(cols[2]),'namespace_pid':int(next(line.split()[-1] for line in (proc/'status').read_text().splitlines() if line.startswith('NSpid:')))})\nassert rows;out['owned_npu_process_rows']=rows;out['top']=cmd(['docker','top',CID,'-eo','pid,ppid,stat,comm,etime']);out['loadavg']=pathlib.Path('/proc/loadavg').read_text();out['meminfo']=pathlib.Path('/proc/meminfo').read_text()\nopener=urllib.request.build_opener(urllib.request.ProxyHandler({}))\nfor endpoint in ['/health','/v1/models','/get_server_info','/metrics']:\n try:\n  with opener.open('http://172.16.12.'+str(NODE)+':'+str(PORT)+endpoint,timeout=10) as response:raw=response.read(8*1024**2+1);assert len(raw)<=8*1024**2\n  dest=archive/(endpoint.replace('/','-')+'.gz');dest.write_bytes(gzip.compress(raw,mtime=0));out[endpoint]={'status':response.status,'body':raw.decode(),'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'archive_sha256':hashlib.sha256(dest.read_bytes()).hexdigest()}\n except Exception as error:out[endpoint]={'error':repr(error)}\npaths=sorted((root/'audit').glob('sdma-*.jsonl'));assert len(paths)<=256;total=0\nfor path in paths:\n raw=path.read_bytes();total+=len(raw);assert len(raw)<=16*1024**2 and total<=64*1024**2;assert not raw or raw.endswith(b'\\n')\n out['persistent_audit'][path.name]={'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'rows':[json.loads(line) for line in raw.splitlines()]}\nprofile=root/'profile';out['profiler_artifacts']=[{'path':str(p.relative_to(root)),'bytes':p.stat().st_size} for p in profile.rglob('*') if p.is_file()] if profile.exists() else []\nout['native_SDK_small_file_snapshots']=[]\nfor sdk_cid in ([CID,META] if NODE==34 else [CID]):\n if sdk_cid==META:\n  result=cmd(['docker','inspect',META]);assert result['rc']==0;d=json.loads(result['stdout'])[0];assert d['Id']==META and d['Image']==IMAGE and d['Config']['Labels']['project_id']=='glm53' and d['Config']['Labels']['run_id']=='20261018T-L08-sglang-C32-ops-window-L04-rollback-v2';out['meta_state']=d['State']\n result=cmd(['docker','exec',sdk_cid,'python3','-c',SDK_SOURCE],90);item={'container_id':sdk_cid,'rc':result['rc'],'stderr':result['stderr']}\n if result['rc']==0:item['files']=json.loads(result['stdout'])\n else:item['stdout']=result['stdout']\n out['native_SDK_small_file_snapshots'].append(item)\nif NODE==34 and NEED_FORMAL:\n path=root/'formal-gates'/FORMAL_RID/'control/cache-gate.json';raw=path.read_bytes();assert len(raw)<=8*1024**2;out['actual_formal_cache_gate']={'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'report':json.loads(raw)}\n"
CPU_HOST='import pathlib\narchive=pathlib.Path(ARCHIVE);assert not archive.exists();archive.mkdir(parents=True)\nimport pathlib,json,gzip,hashlib,re\nout={\'project_id\':\'glm53\',\'model_requests\':0,\'SDK_init_calls\':0}\nif True:\n formal=pathlib.Path(\'/data/wio/inference-foundry/glm53/runs/\'+FORMAL_RID+\'\');output=formal/\'output\';report_raw=(output/\'formal-result.json\').open(\'rb\').read(64*1024**2+1);assert len(report_raw)<=64*1024**2;report=json.loads(report_raw);assert report[\'project_id\']==\'glm53\' and report[\'framework\']==\'sglang\' and report[\'concurrency\']==CONCURRENCY\n out[\'formal_report_identity\']={\'sha256\':hashlib.sha256(report_raw).hexdigest(),\'bytes\':len(report_raw),\'namespace\':report[\'namespace\'],\'phase\':report[\'phase\'],\'baseline_accepted\':report[\'baseline_accepted\']}\n # Independently stream every original full metrics body and rederive occupancy.\n metric=output/\'formal-D-metrics.jsonl.gz\';packed=metric.open(\'rb\').read(512*1024**2+1);assert len(packed)<=512*1024**2;expected=report[\'D_metrics\'];assert hashlib.sha256(packed).hexdigest()==expected[\'raw_archive_sha256\']\n decoded_bytes=0;row_count=0;errors=[];pair=[];peak=None;max_by_DP={};max_skew=0;complete_pairs=0\n with gzip.open(metric,\'rb\') as file:\n  while True:\n   raw=file.readline(24*1024**2+1)\n   if not raw:break\n   assert len(raw)<=24*1024**2 and raw.endswith(b\'\\n\');decoded_bytes+=len(raw);assert decoded_bytes<=8*1024**3\n   row=json.loads(raw);row_count+=1;pair.append(row)\n   if row.get(\'error\'):errors.append({\'node\':row[\'node\'],\'error\':row[\'error\']})\n   else:\n    body=row[\'raw_utf8\'].encode();assert len(body)==row[\'bytes\'] and hashlib.sha256(body).hexdigest()==row[\'sha256\'] and row[\'http_status\']==200\n    actual={}\n    for line in row[\'raw_utf8\'].splitlines():\n     if not line.startswith((\'sglang:num_running_reqs{\',\'sglang:num_queue_reqs{\')):continue\n     engine=int(re.search(r\'dp_rank="([0-9]+)"\',line).group(1));value=float(line.rsplit(\' \',1)[1]);assert value.is_integer() and value>=0\n     role=\'running\' if line.startswith(\'sglang:num_running_reqs{\') else \'waiting\';entry=actual.setdefault(engine,{})\n     if role in entry:assert entry[role]==int(value)\n     entry[role]=int(value)\n    assert set(actual)==set(range(8) if row[\'node\']==36 else range(8,16)) and all(set(x)=={\'running\',\'waiting\'} for x in actual.values())\n    for dp,value in actual.items():\n     recorded=row[\'occupancy\'][str(dp)];assert all(recorded[k]==v for k,v in value.items());max_by_DP[str(dp)]=max(max_by_DP.get(str(dp),0),value[\'running\'])\n   if len(pair)==2:\n    assert {x[\'node\'] for x in pair}=={36,41}\n    if not any(x.get(\'error\') for x in pair):\n     total=sum(v[\'running\'] for x in pair for v in x[\'occupancy\'].values());peak=max(peak or 0,total);complete_pairs+=1;max_skew=max(max_skew,(max(x[\'terminal_perf_counter_ns\'] for x in pair)-min(x[\'terminal_perf_counter_ns\'] for x in pair))/1e9)\n    pair=[]\n assert not pair and row_count==expected[\'sample_count\']*2\n assert complete_pairs==expected[\'complete_sample_count\'] and peak==expected[\'sampled_peak_total_D_running\'] and max_by_DP==expected[\'sampled_peak_D_running_by_DP\']\n out[\'independent_formal_metric_archive_audit\']={\'archive\':str(metric),\'archive_sha256\':hashlib.sha256(packed).hexdigest(),\'archive_bytes\':len(packed),\'decoded_bytes\':decoded_bytes,\'native_HTTP_rows\':row_count,\'sample_pairs\':row_count//2,\'complete_pairs\':complete_pairs,\'errors\':errors,\'sampled_peak_total_D_running\':peak,\'sampled_peak_D_running_by_DP\':max_by_DP,\'max_endpoint_terminal_skew_seconds\':max_skew,\'all_native_bodies_SHA_and_DP_gauges_recomputed\':True,\'scope\':\'Discrete polling occupancy, not exact instantaneous concurrency; original native bodies retained in complete gzip.\'}\n\n'
